"""Split versus Inert: an eigenvalue census of the hyperbolic Berggren generator.

For each odd prime p below a cutoff this demo verifies, from scratch, the whole
chain of equivalences proved in the accompanying paper:

    p = +-1 (mod 8)
      <=> 2 is a quadratic residue mod p
      <=> X^2 - 6X + 1 has two distinct roots in F_p
      <=> M2 = [[1,2,2],[2,1,2],[2,2,3]] has three eigenvalues in F_p
      <=> the resonant frequency of M2 divides p - 1  (rather than p + 1),

and it checks the exact order formula ord_p(M2) = lcm(2, ord_p(U)) with
U = [[3,2],[4,3]].  Any violation would be printed as a MISMATCH; the point of
the demo is that none occur.
"""

from __future__ import annotations

from math import gcd
from typing import List, Optional, Tuple

Matrix = Tuple[Tuple[int, ...], ...]
M2: Matrix = ((1, 2, 2), (2, 1, 2), (2, 2, 3))
U: Matrix = ((3, 2), (4, 3))


def mat_mul(a: Matrix, b: Matrix, mod: int) -> Matrix:
    n = len(a)
    return tuple(
        tuple(sum(a[i][k] * b[k][j] for k in range(n)) % mod for j in range(n))
        for i in range(n)
    )


def mat_pow(a: Matrix, e: int, mod: int) -> Matrix:
    n = len(a)
    r: Matrix = tuple(tuple(1 if i == j else 0 for j in range(n)) for i in range(n))
    b = tuple(tuple(x % mod for x in row) for row in a)
    while e > 0:
        if e & 1:
            r = mat_mul(r, b, mod)
        b = mat_mul(b, b, mod)
        e >>= 1
    return r


def is_identity(a: Matrix, mod: int) -> bool:
    n = len(a)
    return all(a[i][j] % mod == (1 if i == j else 0) % mod
               for i in range(n) for j in range(n))


def primes_up_to(limit: int) -> List[int]:
    sieve = [True] * (limit + 1)
    sieve[0:2] = [False, False]
    for i in range(2, int(limit ** 0.5) + 1):
        if sieve[i]:
            for j in range(i * i, limit + 1, i):
                sieve[j] = False
    return [i for i, ok in enumerate(sieve) if ok]


def divisors(n: int) -> List[int]:
    out: List[int] = []
    i = 1
    while i * i <= n:
        if n % i == 0:
            out.append(i)
            if i != n // i:
                out.append(n // i)
        i += 1
    return sorted(out)


def order_mod(a: Matrix, p: int, bound: int) -> Optional[int]:
    for d in divisors(bound):
        if d >= 1 and is_identity(mat_pow(a, d, p), p):
            return d
    return None


def lcm(a: int, b: int) -> int:
    return a * b // gcd(a, b)


def eigenvalues_mod(p: int) -> List[int]:
    """All roots in F_p of the characteristic polynomial (X+1)(X^2-6X+1)."""
    return sorted({x for x in range(p)
                   if ((x + 1) * (x * x - 6 * x + 1)) % p == 0})


def is_square_mod(a: int, p: int) -> bool:
    return any((x * x - a) % p == 0 for x in range(p))


def main(cutoff: int = 120) -> None:
    print("p    p%8  2 is QR  roots of X^2-6X+1   #eigenvalues  freq   "
          "ord(M2)  lcm(2,ord U)  status")
    print("-" * 95)
    mismatches = 0
    for p in primes_up_to(cutoff):
        if p == 2:
            continue
        qr = is_square_mod(2, p)
        quad_roots = [x for x in range(p) if (x * x - 6 * x + 1) % p == 0]
        eigs = eigenvalues_mod(p)
        freq = p - 1 if p % 8 in (1, 7) else p + 1
        ordm = order_mod(M2, p, 2 * (p * p - 1))
        ordu = order_mod(U, p, p * p - 1)
        assert ordm is not None and ordu is not None
        ok = (
            qr == (p % 8 in (1, 7))
            and qr == (len(quad_roots) == 2)
            and len(eigs) == (3 if qr else 1)
            and freq % ordm == 0
            and ordm == lcm(2, ordu)
        )
        mismatches += 0 if ok else 1
        print(f"{p:<4} {p % 8:<4} {str(qr):<8} {str(quad_roots):<20} "
              f"{len(eigs):<13} {freq:<6} {ordm:<8} {lcm(2, ordu):<13} "
              f"{'ok' if ok else 'MISMATCH'}")
    print("-" * 95)
    print(f"mismatches: {mismatches}")
    print()
    print("Reading the table: the 'QR' column and the 'p%8 in {1,7}' condition")
    print("never disagree (second supplement to quadratic reciprocity); whenever")
    print("they hold, the quadratic factor has two roots and M2 has a full set of")
    print("three eigenvalues in F_p, and the frequency is p-1; otherwise -1 is the")
    print("only eigenvalue in F_p and the frequency is p+1.  The last two columns")
    print("confirm the order formula ord_p(M2) = lcm(2, ord_p(U)).")


if __name__ == "__main__":
    main()

