"""Berggren Resonance Factorization: the p +- 1 engine driven by the hyperbolic
generator of the Pythagorean tree.

The generator M2 = [[1,2,2],[2,1,2],[2,2,3]] has, modulo an odd prime p, a
multiplicative order dividing p-1 when p = +-1 (mod 8) and dividing p+1 when
p = +-3 (mod 8).  For N = p*q, an exponent E that is a multiple of the order at
p but not at q makes every entry of M2^E - I divisible by p while some entry is
not divisible by q; the gcd of that entry with N is then exactly p.
"""

from __future__ import annotations

from math import gcd
from typing import List, Optional, Tuple

Matrix = Tuple[Tuple[int, ...], ...]

M2: Matrix = ((1, 2, 2), (2, 1, 2), (2, 2, 3))


def mat_mul(a: Matrix, b: Matrix, mod: int) -> Matrix:
    return tuple(
        tuple(sum(a[i][k] * b[k][j] for k in range(3)) % mod for j in range(3))
        for i in range(3)
    )


def mat_pow(a: Matrix, e: int, mod: int) -> Matrix:
    result: Matrix = ((1, 0, 0), (0, 1, 0), (0, 0, 1))
    base = tuple(tuple(x % mod for x in row) for row in a)
    while e > 0:
        if e & 1:
            result = mat_mul(result, base, mod)
        base = mat_mul(base, base, mod)
        e >>= 1
    return result


def primes_up_to(limit: int) -> List[int]:
    sieve = [True] * (limit + 1)
    sieve[0:2] = [False, False]
    for i in range(2, int(limit ** 0.5) + 1):
        if sieve[i]:
            for j in range(i * i, limit + 1, i):
                sieve[j] = False
    return [i for i, ok in enumerate(sieve) if ok]


def resonance_gcd(a: Matrix, n: int) -> int:
    """gcd of all entries of (A - I) mod n, together with n."""
    g = 0
    for i in range(3):
        for j in range(3):
            g = gcd(g, (a[i][j] - (1 if i == j else 0)) % n)
    return gcd(g, n)


def berggren_factor(n: int, bound: int, verbose: bool = False
                    ) -> Optional[Tuple[int, int]]:
    """Return (factor, exponent) or None.

    Accumulates E = lcm(1..bound) into M2 modulo n one prime power at a time,
    testing the resonance gcd after each absorption.  Complexity: O(pi(bound))
    modular exponentiations, i.e. ~O(bound) modular multiplications of
    O(log n)-bit numbers, plus one gcd per prime.
    """
    if n % 2 == 0:
        return (2, 1)
    a = tuple(tuple(x % n for x in row) for row in M2)
    e_total = 1
    for r in primes_up_to(bound):
        power = r
        while power * r <= bound:
            power *= r
        a = mat_pow(a, power, n)
        e_total *= power
        g = resonance_gcd(a, n)
        if verbose:
            print(f"  absorbed {power:>4} -> E = {e_total:<12} gcd = {g}")
        if 1 < g < n:
            return (g, e_total)
        if g == n:
            return None  # frequencies aligned; the exponent overshot
    return None


if __name__ == "__main__":
    for n in (15, 143, 3233, 6557, 25777, 1000003 * 1000033):
        out = berggren_factor(n, 200)
        print(f"N = {n:<16} -> {out}")

"""Exact Modular Order of the Hyperbolic Berggren Generator.

For an odd prime p the resonance set of M2 = [[1,2,2],[2,1,2],[2,2,3]] modulo p
is exactly {k : U^k = I in F_p and k even}, where U = [[3,2],[4,3]] is the 2x2
hyperbolic block obtained by conjugating M2 with the integral matrix whose
columns are (1,1,0), (0,0,1), (1,-1,0).  Consequently

        ord_p(M2) = lcm(2, ord_p(U)),

and ord_p(U) divides p-1 if 2 is a quadratic residue mod p (equivalently
p = +-1 mod 8) and divides p+1 otherwise.  This gives an algorithm that never
searches: factor the relevant bound and strip prime factors greedily.
"""

from __future__ import annotations

from math import gcd
from typing import Dict, List, Tuple

Matrix = Tuple[Tuple[int, ...], ...]

M2: Matrix = ((1, 2, 2), (2, 1, 2), (2, 2, 3))
U: Matrix = ((3, 2), (4, 3))


def mat_mul(a: Matrix, b: Matrix, mod: int) -> Matrix:
    n = len(a)
    return tuple(
        tuple(sum(a[i][k] * b[k][j] for k in range(n)) % mod for j in range(n))
        for i in range(n)
    )


def mat_pow(a: Matrix, e: int, mod: int) -> Matrix:
    n = len(a)
    result: Matrix = tuple(
        tuple(1 if i == j else 0 for j in range(n)) for i in range(n)
    )
    base = tuple(tuple(x % mod for x in row) for row in a)
    while e > 0:
        if e & 1:
            result = mat_mul(result, base, mod)
        base = mat_mul(base, base, mod)
        e >>= 1
    return result


def is_identity(a: Matrix, mod: int) -> bool:
    n = len(a)
    return all(a[i][j] % mod == (1 if i == j else 0) % mod
               for i in range(n) for j in range(n))


def factorize(n: int) -> Dict[int, int]:
    out: Dict[int, int] = {}
    d = 2
    while d * d <= n:
        while n % d == 0:
            out[d] = out.get(d, 0) + 1
            n //= d
        d += 1 if d == 2 else 2
    if n > 1:
        out[n] = out.get(n, 0) + 1
    return out


def lcm(a: int, b: int) -> int:
    return a * b // gcd(a, b)


def hyperbolic_block_order(p: int) -> int:
    """ord_p(U), computed by stripping prime factors from p-1 or p+1."""
    bound = p - 1 if p % 8 in (1, 7) else p + 1
    order = bound
    for r, mult in factorize(bound).items():
        for _ in range(mult):
            if order % r == 0 and is_identity(mat_pow(U, order // r, p), p):
                order //= r
            else:
                break
    return order


def berggren_order(p: int) -> int:
    """ord_p(M2) = lcm(2, ord_p(U)).  O(log p) modular exponentiations after
    one factorization of p -+ 1."""
    return lcm(2, hyperbolic_block_order(p))


if __name__ == "__main__":
    for p in (3, 5, 7, 11, 13, 17, 23, 29, 31, 41, 53, 59, 61, 73, 79, 101, 1009):
        pred = p - 1 if p % 8 in (1, 7) else p + 1
        d = berggren_order(p)
        assert is_identity(mat_pow(M2, d, p), p)
        assert pred % d == 0
        print(f"p = {p:>5}  p%8 = {p % 8}  predicted {pred:>5}  "
              f"exact ord = {d:>5}  {'sharp' if d == pred else ''}")

"""The Berggren-Lucas Trace Compositeness Test.

Let t(k) = tr(M2^k) where M2 = [[1,2,2],[2,1,2],[2,2,3]].  Since the
characteristic polynomial of M2 is X^3 - 5X^2 - 5X + 1, Newton's identities give

        t(k+3) = 5 t(k+2) + 5 t(k+1) - t(k),    t(0..3) = 3, 5, 35, 197,

and t(k) = (3+2*sqrt2)^k + (3-2*sqrt2)^k + (-1)^k.  A Frobenius computation on
the hyperbolic block shows that for every odd prime p,

        t(p) = 5   (mod p).

The contrapositive is a Fermat/Lucas-type compositeness test: it never lies
about a prime, and it convicts most composites.  Two implementations are given:
a linear-time recurrence and a logarithmic-time matrix exponentiation.
"""

from __future__ import annotations

from typing import List, Optional, Tuple

Matrix = Tuple[Tuple[int, ...], ...]

M2: Matrix = ((1, 2, 2), (2, 1, 2), (2, 2, 3))


def trace_mod_linear(k: int, mod: int) -> int:
    """t(k) mod `mod` in O(k) additions."""
    a, b, c = 3 % mod, 5 % mod, 35 % mod
    if k == 0:
        return a
    if k == 1:
        return b
    if k == 2:
        return c
    for _ in range(3, k + 1):
        a, b, c = b, c, (5 * c + 5 * b - a) % mod
    return c


def mat_mul(a: Matrix, b: Matrix, mod: int) -> Matrix:
    return tuple(
        tuple(sum(a[i][k] * b[k][j] for k in range(3)) % mod for j in range(3))
        for i in range(3)
    )


def trace_mod_fast(k: int, mod: int) -> int:
    """t(k) mod `mod` in O(log k) matrix multiplications."""
    result: Matrix = ((1, 0, 0), (0, 1, 0), (0, 0, 1))
    base = tuple(tuple(x % mod for x in row) for row in M2)
    e = k
    while e > 0:
        if e & 1:
            result = mat_mul(result, base, mod)
        base = mat_mul(base, base, mod)
        e >>= 1
    return sum(result[i][i] for i in range(3)) % mod


def berggren_composite_witness(n: int) -> bool:
    """True if the test certifies that odd n > 1 is composite."""
    if n % 2 == 0:
        return n != 2
    return trace_mod_fast(n, n) != 5 % n


def two_sided_test(n: int) -> bool:
    """Strengthened test: t(n) = 5 and t(n+1) = t(n-1) (mod n).
    Returns True when n passes (i.e. is 'probably prime' for this test)."""
    if n < 3 or n % 2 == 0:
        return n == 2
    return (trace_mod_fast(n, n) == 5 % n
            and trace_mod_fast(n + 1, n) == trace_mod_fast(n - 1, n))


if __name__ == "__main__":
    def is_prime(n: int) -> bool:
        if n < 2:
            return False
        d = 2
        while d * d <= n:
            if n % d == 0:
                return False
            d += 1
        return True

    print("t(k) for k = 0..9:",
          [trace_mod_linear(k, 10 ** 12) for k in range(10)])

    weak, strong = [], []
    for n in range(9, 5000, 2):
        if is_prime(n):
            assert not berggren_composite_witness(n), f"false witness at {n}"
            continue
        if not berggren_composite_witness(n):
            weak.append(n)
        if two_sided_test(n):
            strong.append(n)
    print("one-sided pseudoprimes below 5000:", weak)
    print("two-sided pseudoprimes below 5000:", strong)
